package com.shop.orders;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

// Orders API of an existing service: hand-written, never generated by gherkin-ai.
@RestController
@RequestMapping("/orders")
public class OrderController {
  private final Map<String, String> statuses = new ConcurrentHashMap<>();

  @PostMapping
  public ResponseEntity<Map<String, String>> placeOrder() {
    String id = String.valueOf(statuses.size() + 1);
    statuses.put(id, "PENDING");
    return ResponseEntity.status(201).body(Map.of("id", id, "status", "PENDING"));
  }

  @PostMapping("/{id}/cancel")
  public ResponseEntity<Map<String, String>> cancelOrder(@PathVariable String id) {
    if (!statuses.containsKey(id)) return ResponseEntity.notFound().build();
    statuses.put(id, "CANCELLED");
    return ResponseEntity.ok(Map.of("id", id, "status", "CANCELLED"));
  }
}
